#include <iostream>
#include <string>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::string s;
    std::cin >> n;
    std::cin >> s;

    int d = 0;
    for (char c : s) {
        if (c == '+') {
            d++;
        } else {
            if (d == 0) d = 1;
            d--;
        }
    }
    std::cout << d << '\n';
    return 0;
}

